  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation)
  }

  /** helper function to set the values of all input ports.
   * @param decision_disposition payload for data port decision_disposition
   * @param battery_assessment payload for data port battery_assessment
   */
  def put_concrete_inputs(decision_disposition : Drone_Lifecycle_Governor.Decision_Disposition,
                          battery_assessment : Drone_Lifecycle_Governor.Battery_Assessment_Value.Type): Unit = {
    put_decision_disposition(decision_disposition)
    put_battery_assessment(battery_assessment)
  }


  /** helper function to check Attention_Derivation_governor_process_attention_derivation's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param attention_status method that will be called with the value of the outgoing data
   *        port 'attention_status'.
   */
  def check_concrete_output(attention_status: Drone_Lifecycle_Governor.Attention_Status.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val attention_statusValue: Drone_Lifecycle_Governor.Attention_Status.Type = get_attention_status().get
    if(!attention_status(attention_statusValue)) {
      testFailures = testFailures :+ st"'attention_status' did not match expected: value of the outgoing data port is ${attention_statusValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_decision_disposition(value : Drone_Lifecycle_Governor.Decision_Disposition): Unit = {
    Art.insertInInfrastructurePort(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation.operational_api.decision_disposition_Id, Drone_Lifecycle_Governor.Decision_Disposition_Payload(value))
  }

  // setter for in DataPort
  def put_battery_assessment(value : Drone_Lifecycle_Governor.Battery_Assessment_Value.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation.operational_api.battery_assessment_Id, Drone_Lifecycle_Governor.Battery_Assessment_Value_Payload(value))
  }

  // getter for out DataPort
  def get_attention_status(): Option[Drone_Lifecycle_Governor.Attention_Status.Type] = {
    val value: Option[Drone_Lifecycle_Governor.Attention_Status.Type] = get_attention_status_payload() match {
      case Some(Drone_Lifecycle_Governor.Attention_Status_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port attention_status.  Expecting 'Drone_Lifecycle_Governor.Attention_Status_Payload' but received ${v}")
      case _ => None[Drone_Lifecycle_Governor.Attention_Status.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_attention_status_payload(): Option[Drone_Lifecycle_Governor.Attention_Status_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation.initialization_api.attention_status_Id).asInstanceOf[Option[Drone_Lifecycle_Governor.Attention_Status_Payload]]
  }

}
